setup.src/public.ts:
export type ParseResult = {
  readonly ok: true;
  readonly value: string;
};

export const isParseResult = (value: unknown): value is ParseResult =>
  typeof value === "object" &&
  value !== null &&
  (value as { readonly ok?: unknown }).ok === true &&
  typeof (value as { readonly value?: unknown }).value === "string";

setup.src/parser.ts:
import { trimToken } from "./lexer";
import type { ParseResult } from "./public";

export const parseToken = (raw: string): ParseResult => {
  return { ok: true, value: trimToken(raw) };
};

setup.test/parser.test.ts:
import { expect, test } from "bun:test";
import { parseToken } from "../src/parser";

test("parses non-empty token", () => {
  expect(parseToken(" abc ")).toEqual({ ok: true, value: "abc" });
});

setup.test/public-contract.test.ts:
import { expect, test } from "bun:test";
import { parseToken } from "../src/parser";
import { isParseResult } from "../src/public";

test("parseToken output satisfies isParseResult", () => {
  expect(isParseResult(parseToken(" abc "))).toBe(true);
});
